import re
import sqlite3

DB_PATH = "/var/lib/bank/core.db"
_ID_PATTERN = re.compile(r"^[A-Za-z0-9_-]{6,64}$")


def _valid_id(value: str) -> bool:
    return isinstance(value, str) and bool(_ID_PATTERN.match(value))


def delete_saved_payee(customer_id: str, payee_id: str, confirm: bool) -> dict:
    if not _valid_id(customer_id):
        return {"deleted": False, "error": "invalid customer_id"}
    if not _valid_id(payee_id):
        return {"deleted": False, "error": "invalid payee_id"}
    if confirm is not True:
        return {"deleted": False, "error": "confirmation required to delete payee"}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        payee = conn.execute(
            "SELECT id, nickname, customer_id FROM payees WHERE id = ?",
            (payee_id,),
        ).fetchone()
        if payee is None:
            return {"deleted": False, "error": "payee not found"}
        if payee["customer_id"] != customer_id:
            return {"deleted": False, "error": "payee does not belong to this customer"}
        pending = conn.execute(
            "SELECT COUNT(*) FROM scheduled_payments WHERE payee_id = ? AND status = 'pending'",
            (payee_id,),
        ).fetchone()[0]
        if pending:
            return {
                "deleted": False,
                "error": f"payee has {pending} pending scheduled payment(s); cancel them first",
            }
        cur = conn.execute(
            "DELETE FROM payees WHERE id = ? AND customer_id = ?",
            (payee_id, customer_id),
        )
        conn.commit()
        return {
            "deleted": cur.rowcount == 1,
            "payee_id": payee_id,
            "nickname": payee["nickname"],
        }
    finally:
        conn.close()
